function interpolateMultiplierBps(quantity) {
  if (quantity <= multiplierAnchors[0][0]) {
    return Math.round(multiplierAnchors[0][1]);
  }

  const lastAnchor = multiplierAnchors[multiplierAnchors.length - 1];
  if (quantity >= lastAnchor[0]) {
    return Math.round(lastAnchor[1]);
  }

  for (let index = 1; index < multiplierAnchors.length; index += 1) {
    const [rightCoins, rightBps] = multiplierAnchors[index];
    if (quantity > rightCoins) continue;

    const [leftCoins, leftBps] = multiplierAnchors[index - 1];
    const progress = (quantity - leftCoins) / (rightCoins - leftCoins);
    return Math.round(leftBps + (rightBps - leftBps) * progress);
  }

  return 10_000;
}

