const multiplierMapCache = new Map();

function multiplierMap(range) {
  const cacheKey = `${range.minimum}:${range.maximum}:${range.increment}`;
  if (multiplierMapCache.has(cacheKey)) {
    return multiplierMapCache.get(cacheKey);
  }

  const map = {};
  for (
    let quantity = range.minimum;
    quantity <= range.maximum;
    quantity += range.increment
  ) {
    map[String(quantity)] = interpolateMultiplierBps(quantity);
  }

  multiplierMapCache.set(cacheKey, map);
  return map;
}

