    }
  }
  return rates[5];
}

function multiplierFor(rule, quantity) {
  const direct = rule.multipliers_basis_points[String(quantity)];
  if (Number.isInteger(direct) && direct > 0) {
    return direct;
  }

  // console_fast compares itself with the normal formula even above the
  // normal storefront maximum (2M). Preserve the old floor-lookup behavior by
  // carrying the terminal normal multiplier forward for larger quantities.
  const range = settings.legalRanges[rule.group];
  if (range && quantity > range.maximum) {
    const terminal = rule.multipliers_basis_points[String(range.maximum)];
    if (Number.isInteger(terminal) && terminal > 0) {
      return terminal;
    }
  }

  throw new Error(`No multiplier covers ${rule.group} ${quantity}`);
