  const rateNumerator = BigInt(quantity) * BigInt(rate) * BigInt(multiplier);
  const feeGap = Math.max(0, 1_000_000 - quantity);
  const feeNumerator =
    BigInt(rule.service_fee_halalah) * BigInt(feeGap) * 10_000n;
  const denominator =
    1_000_000n * BigInt(rule.discount_divisor_basis_points) * 100n;
  const rounded = roundHalfUpBigInt(rateNumerator + feeNumerator, denominator);
